const test = require('node:test');
const assert = require('node:assert');

const { getDiscountRate, finalPrice } = require('/Users/johnss51/Development/agents/hyperpowers/evals/results/systematic-debugging-red-command-first-claude-auto-20260912T094836Z-943f/coding-agent-workdir/src/pricing.js');

test('unknown code charges full price', () => {
  assert.strictEqual(finalPrice(100, 'BOGUS'), 100);
});

test('unknown code has a zero discount rate', () => {
  assert.strictEqual(getDiscountRate('BOGUS'), 0);
});

test('known codes still discount', () => {
  assert.strictEqual(finalPrice(100, 'SAVE10'), 90);
  assert.strictEqual(finalPrice(100, 'SAVE20'), 80);
  assert.strictEqual(finalPrice(100, 'HALFOFF'), 50);
});

test('missing code charges full price', () => {
  assert.strictEqual(finalPrice(100, undefined), 100);
});

